import app.template.extension.extension.*;import java.util.*;import java.util.concurrent.*;
public class ReplayControllerTest {static void check(boolean b,String m){if(!b)throw new AssertionError(m);}public static void main(String[] args)throws Exception{CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1),done=new CountDownLatch(1);ReplayEngine.Spec spec=new ReplayEngine.Spec("1.2.3","public",0,1,161,1000,1);ReplayController.Factory factory=(ip,s)->new ReplayEngine.Transport(){public String probe(ReplayEngine.Spec x){return "02:01:02:03:04:05";}public String request(ReplayEngine.Spec x)throws Exception{entered.countDown();release.await();return "integer:2";}public void close(){}};ReplayController.Listener first=()->{};ReplayController.attach(first);check(ReplayController.start("192.0.2.1",Arrays.asList(spec),Collections.singletonMap("1.2.3","integer:1"),"02:01:02:03:04:05",factory),"start");check(entered.await(3,TimeUnit.SECONDS),"worker running");ReplayController.detach(first);ReplayController.Listener next=()->{if(!ReplayController.isRunning())done.countDown();};ReplayController.attach(next);release.countDown();check(done.await(3,TimeUnit.SECONDS),"new screen receives completion");ReplayController.Outcome result=ReplayController.takeOutcome();check(result!=null&&result.result!=null&&result.result.changes.size()==1,"result survives screen replacement");check(ReplayController.takeOutcome()==null,"result delivered once");ReplayController.detach(next);
 CountDownLatch sending=new CountDownLatch(1),closed=new CountDownLatch(1),stopped=new CountDownLatch(1);java.util.concurrent.atomic.AtomicInteger sends=new java.util.concurrent.atomic.AtomicInteger();ReplayController.Listener cancelListener=()->{if(!ReplayController.isRunning())stopped.countDown();};ReplayController.attach(cancelListener);ReplayController.Factory slow=(ip,firstSpec)->new ReplayEngine.Transport(){public String probe(ReplayEngine.Spec x){return "02:01:02:03:04:05";}public String request(ReplayEngine.Spec x)throws Exception{sends.incrementAndGet();sending.countDown();closed.await();return "integer:2";}public void close(){closed.countDown();}};
 check(ReplayController.start("192.0.2.1",Arrays.asList(spec,spec),Collections.singletonMap("1.2.3","integer:1"),"02:01:02:03:04:05",slow),"start cancellable replay");check(sending.await(3,TimeUnit.SECONDS),"first request began");ReplayController.cancel();check(stopped.await(3,TimeUnit.SECONDS),"cancel finishes replay");check(sends.get()==1&&ReplayController.peekOutcome()==null,"cancel stops further requests without showing a result");ReplayController.detach(cancelListener);
 CountDownLatch saved=new CountDownLatch(1);java.util.concurrent.atomic.AtomicReference<ReplayEngine.Result> persisted=new java.util.concurrent.atomic.AtomicReference<>();
 ReplayController.Factory immediate=(ip,firstSpec)->new ReplayEngine.Transport(){public String probe(ReplayEngine.Spec x){return "02:01:02:03:04:05";}public String request(ReplayEngine.Spec x){return "integer:2";}public void close(){}};
 check(ReplayController.startRecorded("192.0.2.1",Arrays.asList(spec),Arrays.asList("integer:1"),"02:01:02:03:04:05",7,immediate,r->{persisted.set(r);saved.countDown();}),"start recorded replay");
 check(saved.await(3,TimeUnit.SECONDS)&&persisted.get().responses.equals(Arrays.asList("integer:2")),"completed replay must expose its exact responses for persistence");
 CountDownLatch pause=new CountDownLatch(1),resume=new CountDownLatch(1),progressDone=new CountDownLatch(1);
 ReplayController.Factory progress=(ip,firstSpec)->new ReplayEngine.Transport(){int n;public String probe(ReplayEngine.Spec x){return "02:01:02:03:04:05";}public String request(ReplayEngine.Spec x)throws Exception{if(++n==2){pause.countDown();resume.await();throw new java.net.SocketTimeoutException();}return "integer:2";}public void close(){}};
 ReplayController.Listener progressListener=()->{if(!ReplayController.isRunning())progressDone.countDown();};ReplayController.attach(progressListener);
 check(ReplayController.startRecorded("192.0.2.1",Arrays.asList(spec,spec,spec),Arrays.asList("integer:1","integer:1","integer:1"),"02:01:02:03:04:05",8,progress,null),"start progress replay");
 check(pause.await(3,TimeUnit.SECONDS),"second request entered");check(ReplayController.completed()==1&&ReplayController.total()==3,"progress must count completed requests");resume.countDown();check(progressDone.await(3,TimeUnit.SECONDS),"failed replay finished");
 ReplayController.Outcome failed=ReplayController.takeOutcome();check(failed.error.contains("2 of 3")&&failed.error.toLowerCase().contains("timed out"),"show request position and timeout without leaking details");ReplayController.detach(progressListener);
 System.out.println("Replay screen lifecycle and cancellation checks passed");}}

